-- =====================================================================
-- NEW-056 学生社团活动与经费管理系统 数据库初始化脚本
-- 库名 new_056，MySQL 8，utf8mb4；可重复执行（先 DROP 再建）
-- 生成脚本：gen/make_sql.py
-- =====================================================================
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS `new_056`;
CREATE DATABASE `new_056` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_056`;
SET FOREIGN_KEY_CHECKS = 0;


CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(50) NOT NULL COMMENT '登录账号',
  `password` varchar(100) NOT NULL COMMENT 'BCrypt 密码',
  `real_name` varchar(50) NOT NULL COMMENT '真实姓名',
  `user_no` varchar(32) DEFAULT NULL COMMENT '学号/工号',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `email` varchar(80) DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像相对路径',
  `gender` varchar(10) DEFAULT NULL COMMENT '男/女',
  `dept_id` bigint DEFAULT NULL COMMENT '所属院系ID',
  `dept_name` varchar(60) DEFAULT NULL COMMENT '所属院系',
  `title` varchar(40) DEFAULT NULL COMMENT '职称/年级',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `credit_score` int NOT NULL DEFAULT 100 COMMENT '诚信分',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近登录时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_user_no` (`user_no`),
  KEY `idx_dept` (`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户';

CREATE TABLE `sys_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_name` varchar(50) NOT NULL COMMENT '角色名称',
  `role_code` varchar(50) NOT NULL COMMENT '角色编码 ROLE_XXX',
  `data_scope` varchar(20) NOT NULL DEFAULT '本人' COMMENT '本人/本部门/全部',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '说明',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_code` (`role_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色';

CREATE TABLE `sys_user_role` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户',
  `role_id` bigint NOT NULL COMMENT '角色',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_role` (`user_id`, `role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户角色';

CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '上级菜单，0为根',
  `menu_name` varchar(50) NOT NULL COMMENT '菜单名称',
  `path` varchar(100) DEFAULT NULL COMMENT '路由地址',
  `component` varchar(150) DEFAULT NULL COMMENT '组件路径',
  `perms` varchar(100) DEFAULT NULL COMMENT '权限标识',
  `menu_type` varchar(20) NOT NULL DEFAULT '菜单' COMMENT '目录/菜单/按钮',
  `icon` varchar(40) DEFAULT NULL COMMENT '图标名',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序',
  `visible` tinyint NOT NULL DEFAULT 1 COMMENT '1显示 0隐藏',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='菜单权限';

CREATE TABLE `sys_role_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role_id` bigint NOT NULL COMMENT '角色',
  `menu_id` bigint NOT NULL COMMENT '菜单',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_menu` (`role_id`, `menu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色菜单';

CREATE TABLE `sys_dict_type` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_name` varchar(60) NOT NULL COMMENT '字典名称',
  `dict_type` varchar(60) NOT NULL COMMENT '字典编码',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dict_type` (`dict_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='字典类型';

CREATE TABLE `sys_dict_data` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_type` varchar(60) NOT NULL COMMENT '字典编码',
  `dict_label` varchar(60) NOT NULL COMMENT '显示标签',
  `dict_value` varchar(60) NOT NULL COMMENT '字典值',
  `tag_type` varchar(20) DEFAULT NULL COMMENT '标签样式',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_dict_type` (`dict_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='字典数据';

CREATE TABLE `sys_file` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `file_name` varchar(150) NOT NULL COMMENT '原文件名',
  `file_path` varchar(255) NOT NULL COMMENT '相对路径 /uploads/...',
  `file_size` bigint NOT NULL DEFAULT 0 COMMENT '字节',
  `file_type` varchar(40) DEFAULT NULL COMMENT '扩展名',
  `biz_type` varchar(40) DEFAULT NULL COMMENT '业务类型',
  `biz_id` bigint DEFAULT NULL COMMENT '业务ID',
  `uploader_id` bigint DEFAULT NULL COMMENT '上传人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_biz` (`biz_type`, `biz_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='上传文件';

CREATE TABLE `sys_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(150) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '正文',
  `notice_type` varchar(20) NOT NULL DEFAULT '通知' COMMENT '通知/公告/考试提醒',
  `publish_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `publisher_id` bigint DEFAULT NULL COMMENT '发布人',
  `status` varchar(20) NOT NULL DEFAULT '已发布' COMMENT '草稿/已发布/已下线',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公告';

CREATE TABLE `sys_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `receiver_id` bigint NOT NULL COMMENT '接收人',
  `title` varchar(150) NOT NULL COMMENT '标题',
  `content` varchar(500) NOT NULL COMMENT '内容',
  `msg_type` varchar(30) NOT NULL DEFAULT '系统通知' COMMENT '审核/批阅/成绩/预警/系统通知',
  `biz_type` varchar(40) DEFAULT NULL COMMENT '业务类型',
  `biz_id` bigint DEFAULT NULL COMMENT '业务ID',
  `read_flag` tinyint NOT NULL DEFAULT 0 COMMENT '0未读 1已读',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_receiver_read` (`receiver_id`, `read_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='站内消息';

CREATE TABLE `sys_oper_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `module` varchar(40) NOT NULL COMMENT '模块',
  `oper_type` varchar(30) NOT NULL COMMENT '操作类型',
  `biz_no` varchar(50) DEFAULT NULL COMMENT '业务编号',
  `content` varchar(500) DEFAULT NULL COMMENT '操作内容',
  `oper_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `oper_name` varchar(50) DEFAULT NULL COMMENT '操作人',
  `oper_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `ip` varchar(64) DEFAULT NULL COMMENT 'IP',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_oper_time` (`oper_time`),
  KEY `idx_biz_no` (`biz_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志';


-- ============================ 业务表 ============================
CREATE TABLE `club` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `club_no` varchar(32) NOT NULL COMMENT '规则 ST+2位类别码+3位序号，全局唯一',
  `club_name` varchar(60) NOT NULL COMMENT '全校唯一，不得含校外机构名称',
  `club_type` varchar(20) NOT NULL DEFAULT '学术科技' COMMENT '学术科技/文艺体育/公益实践/创新创业',
  `founded_date` date NOT NULL COMMENT '不早于学校建校年份',
  `advisor_id` bigint NOT NULL COMMENT '关联 sys_user.id，须为在职教职工',
  `president_id` bigint NOT NULL COMMENT '关联 sys_user.id，须为在册成员',
  `member_count` int NOT NULL DEFAULT 0 COMMENT '由成员表统计，不得为负',
  `fund_limit` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '0至100000，按社团星级配置',
  `star_level` tinyint NOT NULL DEFAULT 3 COMMENT '1至5星，影响经费上限与场地优先级',
  `review_year` int NOT NULL DEFAULT 2026 COMMENT '四位年份，同一社团同年度一条',
  `status` varchar(20) NOT NULL DEFAULT '正常' COMMENT '待注册/正常/整改中/已注销',
  `review_remark` varchar(200) DEFAULT NULL COMMENT '整改或注销时必填',
  `cover_url` varchar(255) DEFAULT NULL COMMENT '社团封面，本地 /uploads/seed/club/NN.jpg',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_club_no` (`club_no`),
  UNIQUE KEY `uk_club_name` (`club_name`),
  KEY `idx_type_status` (`club_type`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='社团';

CREATE TABLE `club_member` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `member_no` varchar(32) NOT NULL COMMENT '规则 CY+社团码+4位序号，全局唯一',
  `club_id` bigint NOT NULL COMMENT '关联 club.id',
  `student_id` bigint NOT NULL COMMENT '关联 sys_user.id，同一社团仅一条在册记录',
  `dept_id` bigint NOT NULL COMMENT '关联院系编号，用于成员结构统计',
  `dept_name` varchar(60) NOT NULL COMMENT '院系名称冗余，列表直接展示',
  `join_date` date NOT NULL COMMENT '不早于社团成立日期',
  `member_role` varchar(20) NOT NULL DEFAULT '成员' COMMENT '成员/干事/部长/副社长/社长',
  `activity_count` int NOT NULL DEFAULT 0 COMMENT '签到成功后加1',
  `service_hours` decimal(6,1) NOT NULL DEFAULT 0.0 COMMENT '按活动时长累加，用于评优',
  `status` varchar(20) NOT NULL DEFAULT '在册' COMMENT '在册/已退出/已除名',
  `quit_reason` varchar(200) DEFAULT NULL COMMENT '退出或除名时必填',
  `avatar_url` varchar(255) DEFAULT NULL COMMENT '成员头像，本地 /uploads/seed/avatar/NN.jpg',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_member_no` (`member_no`),
  UNIQUE KEY `uk_club_student` (`club_id`, `student_id`),
  KEY `idx_club_status` (`club_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='社团成员';

CREATE TABLE `activity` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_no` varchar(32) NOT NULL COMMENT '规则 HD+yyMMdd+3位序号，全局唯一',
  `club_id` bigint NOT NULL COMMENT '关联 club.id，状态须为正常',
  `activity_name` varchar(100) NOT NULL COMMENT '4至60字，含社团名称便于识别',
  `activity_type` varchar(20) NOT NULL DEFAULT '讲座' COMMENT '讲座/比赛/演出/志愿服务/招新/社会实践',
  `start_time` datetime NOT NULL COMMENT '须晚于申报时间24小时',
  `end_time` datetime NOT NULL COMMENT '晚于开始时间，单次不超过3天',
  `place_name` varchar(100) NOT NULL COMMENT '填写校内场地名称，需与场地借用单一致',
  `place_capacity` int NOT NULL DEFAULT 0 COMMENT '场地容量，用于人数匹配因子',
  `expect_count` int NOT NULL DEFAULT 0 COMMENT '1至2000，不得超过场地容量',
  `actual_count` int NOT NULL DEFAULT 0 COMMENT '由签到统计，不得超过预计人数的120%',
  `budget_total` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '0至50000，不得超过社团年度剩余额度',
  `spent_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '已发生支出，由报销单汇总',
  `feasibility_score` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '0至100，立项时计算并留档',
  `plan_desc` varchar(600) DEFAULT NULL COMMENT '活动方案说明',
  `cover_url` varchar(255) DEFAULT NULL COMMENT '活动照片，本地 /uploads/seed/activity/NN.jpg',
  `status` varchar(20) NOT NULL DEFAULT '待审批' COMMENT '待审批/已驳回/已立项/进行中/已结束/已结项',
  `reject_reason` varchar(200) DEFAULT NULL COMMENT '驳回原因，展示给社团',
  `submit_count` int NOT NULL DEFAULT 1 COMMENT '提交次数，驳回后重提累加',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_activity_no` (`activity_no`),
  KEY `idx_club_status` (`club_id`, `status`),
  KEY `idx_start_time` (`start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='社团活动';

CREATE TABLE `activity_signup` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `signup_no` varchar(32) NOT NULL COMMENT '规则 BM+活动号后6位+4位序号，全局唯一',
  `activity_id` bigint NOT NULL COMMENT '关联 activity.id，仅已立项活动可报名',
  `student_id` bigint NOT NULL COMMENT '关联 sys_user.id，同一活动不可重复报名',
  `signup_type` varchar(20) NOT NULL DEFAULT '线上' COMMENT '线上/现场',
  `signup_time` datetime NOT NULL COMMENT '晚于活动开始时间记为现场报名',
  `checkin_time` datetime DEFAULT NULL COMMENT '签到口令校验通过时写入',
  `checkout_time` datetime DEFAULT NULL COMMENT '晚于签到时间，用于计算服务时长',
  `checkin_status` varchar(20) NOT NULL DEFAULT '未签到' COMMENT '未签到/已签到/迟到/缺席/已请假',
  `checkin_code` varchar(10) DEFAULT NULL COMMENT '6位数字，活动开始前10分钟生成',
  `cancel_flag` tinyint NOT NULL DEFAULT 0 COMMENT '1表示学生取消报名，取消后释放名额',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_signup_no` (`signup_no`),
  UNIQUE KEY `uk_activity_student` (`activity_id`, `student_id`),
  KEY `idx_activity_status` (`activity_id`, `checkin_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='活动报名';

CREATE TABLE `budget` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `budget_no` varchar(32) NOT NULL COMMENT '规则 YS+活动号后6位+2位序号，全局唯一',
  `activity_id` bigint NOT NULL COMMENT '关联 activity.id',
  `club_id` bigint NOT NULL COMMENT '关联 club.id，用于年度额度校验',
  `item_name` varchar(50) NOT NULL COMMENT '如场地布置、宣传物料、交通补贴',
  `item_type` varchar(20) NOT NULL DEFAULT '物料' COMMENT '场地/物料/宣传/交通/劳务/其他',
  `apply_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '0.01至50000，后端校验',
  `amount_basis` varchar(300) NOT NULL COMMENT '不少于20字，写明单价与数量',
  `approve_amount` decimal(10,2) DEFAULT NULL COMMENT '不得高于申请金额',
  `auditor_id` bigint DEFAULT NULL COMMENT '关联 sys_user.id，校团委干事',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `status` varchar(20) NOT NULL DEFAULT '待审核' COMMENT '待审核/已通过/已调减/已驳回',
  `audit_remark` varchar(200) DEFAULT NULL COMMENT '调减或驳回时必填',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_budget_no` (`budget_no`),
  KEY `idx_activity_item` (`activity_id`, `item_type`),
  KEY `idx_club_status` (`club_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='活动预算';

CREATE TABLE `expense` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `expense_no` varchar(32) NOT NULL COMMENT '规则 BX+yyMMdd+4位序号，全局唯一',
  `activity_id` bigint NOT NULL COMMENT '关联 activity.id，须为已结束或已结项',
  `club_id` bigint NOT NULL COMMENT '关联 club.id',
  `budget_id` bigint NOT NULL COMMENT '关联 budget.id，金额不得超过审核金额',
  `applicant_id` bigint NOT NULL COMMENT '关联 sys_user.id，须为社长或财务干事',
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '0.01至50000，且不超过预算审核金额',
  `invoice_count` tinyint NOT NULL DEFAULT 0 COMMENT '0至20，金额超过500元至少1张',
  `invoice_urls` varchar(500) NOT NULL COMMENT 'PDF或图片相对路径，最多10个',
  `pay_type` varchar(20) NOT NULL DEFAULT '校内转账' COMMENT '校内转账/现金，不接在线支付',
  `submit_time` datetime NOT NULL COMMENT '活动结束后30天内提交，逾期需说明',
  `pay_time` datetime DEFAULT NULL COMMENT '财务登记支付时写入',
  `status` varchar(20) NOT NULL DEFAULT '待初审' COMMENT '待初审/待财务复核/已支付/已驳回/已撤回',
  `audit_remark` varchar(200) DEFAULT NULL COMMENT '复核意见',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_expense_no` (`expense_no`),
  KEY `idx_activity_status` (`activity_id`, `status`),
  KEY `idx_club_status` (`club_id`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='费用报销';

CREATE TABLE `fund_flow` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `flow_no` varchar(32) NOT NULL COMMENT '规则 LS+yyMMdd+5位序号，全局唯一',
  `club_id` bigint NOT NULL COMMENT '关联 club.id',
  `biz_type` varchar(20) NOT NULL COMMENT '会费收入/学校拨款/赞助收入/活动支出/报销支出',
  `biz_id` bigint DEFAULT NULL COMMENT '按类型关联 expense.id 或拨款单',
  `direction` varchar(10) NOT NULL DEFAULT '支出' COMMENT '收入/支出',
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '0.01至100000',
  `balance_after` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '不得为负，为负时拒绝记账',
  `occur_date` date NOT NULL COMMENT '不得晚于当前日期',
  `operator_id` bigint NOT NULL COMMENT '关联 sys_user.id，财务人员',
  `remark` varchar(200) DEFAULT NULL COMMENT '收入类必填来源说明',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_flow_no` (`flow_no`),
  KEY `idx_club_date` (`club_id`, `occur_date`),
  KEY `idx_biz` (`biz_type`, `biz_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='经费流水';

CREATE TABLE `fund_disclosure` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `disclosure_no` varchar(32) NOT NULL COMMENT '规则 GS+社团码+年度，全局唯一',
  `club_id` bigint NOT NULL COMMENT '关联 club.id',
  `period` varchar(20) NOT NULL COMMENT '如2026-01至2026-06，同社团同期间唯一',
  `income_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '由经费流水汇总，不允许手工修改',
  `expense_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '由经费流水汇总',
  `balance_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收入减支出，须与流水余额一致',
  `activity_count` int NOT NULL DEFAULT 0 COMMENT '公示期间已结项活动数',
  `publish_start` date NOT NULL COMMENT '不早于期间结束日',
  `publish_end` date NOT NULL COMMENT '开始日起不少于7天',
  `objection_count` int NOT NULL DEFAULT 0 COMMENT '成员提交异议时累加',
  `status` varchar(20) NOT NULL DEFAULT '待公示' COMMENT '待公示/公示中/已归档',
  `notice_url` varchar(255) DEFAULT NULL COMMENT '公示配图，本地 /uploads/seed/notice/NN.jpg',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_disclosure_no` (`disclosure_no`),
  UNIQUE KEY `uk_club_period` (`club_id`, `period`),
  KEY `idx_status_publish` (`status`, `publish_start`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='经费公示';

CREATE TABLE `fund_objection` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `objection_no` varchar(32) NOT NULL COMMENT '规则 YY+yyMMdd+4位序号',
  `disclosure_id` bigint NOT NULL COMMENT '关联 fund_disclosure.id',
  `club_id` bigint NOT NULL COMMENT '关联 club.id',
  `item_type` varchar(20) NOT NULL COMMENT '异议科目类型，与 budget.item_type 一致',
  `item_name` varchar(50) DEFAULT NULL COMMENT '具体科目名称',
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '异议涉及金额',
  `reason` varchar(300) NOT NULL COMMENT '异议理由，不少于10字',
  `applicant_id` bigint NOT NULL COMMENT '提出人 sys_user.id',
  `handle_status` varchar(20) NOT NULL DEFAULT '待答复' COMMENT '待答复/已答复/已冲正/已驳回',
  `reply_content` varchar(300) DEFAULT NULL COMMENT '校团委答复内容',
  `reply_time` datetime DEFAULT NULL COMMENT '答复时间',
  `handler_id` bigint DEFAULT NULL COMMENT '答复人 sys_user.id',
  `create_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '关联 sys_user.id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时自动刷新',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '0正常 1删除，查询默认过滤',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁，更新时校验并加1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_objection_no` (`objection_no`),
  KEY `idx_disclosure` (`disclosure_id`),
  KEY `idx_club_status` (`club_id`, `handle_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='经费公示异议';

-- ====================== 创新点：活动可行性评分三张表 ======================
CREATE TABLE `feasibility_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rule_name` varchar(60) NOT NULL COMMENT '规则名称',
  `rule_version` varchar(20) NOT NULL COMMENT '版本号，如 V1.0，全局唯一',
  `weight_budget` decimal(5,2) NOT NULL DEFAULT 25.00 COMMENT '预算合理性权重（%）',
  `weight_venue` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT '场地时段冲突权重（%）',
  `weight_capacity` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT '人数容量匹配权重（%）',
  `weight_history` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT '历史同类活动效果权重（%）',
  `weight_club` decimal(5,2) NOT NULL DEFAULT 15.00 COMMENT '年审与经费余额权重（%）',
  `level_a` decimal(5,1) NOT NULL DEFAULT 85.0 COMMENT 'A 级下限',
  `level_b` decimal(5,1) NOT NULL DEFAULT 70.0 COMMENT 'B 级下限',
  `level_c` decimal(5,1) NOT NULL DEFAULT 55.0 COMMENT 'C 级下限',
  `status` varchar(20) NOT NULL DEFAULT '生效' COMMENT '生效/历史',
  `effective_time` datetime NOT NULL COMMENT '生效时间',
  `remark` varchar(200) DEFAULT NULL COMMENT '调整说明',
  `create_by` bigint DEFAULT NULL COMMENT '调整人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_version` (`rule_version`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='可行性评分规则';

CREATE TABLE `feasibility_snapshot` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `activity_id` bigint NOT NULL COMMENT '关联 activity.id',
  `rule_id` bigint NOT NULL COMMENT '计算所用规则 id',
  `rule_version` varchar(20) NOT NULL COMMENT '规则版本快照',
  `score_budget` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '预算合理性得分',
  `score_venue` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '场地时段得分',
  `score_capacity` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '人数容量得分',
  `score_history` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '历史效果得分',
  `score_club` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '年审与经费得分',
  `total_score` decimal(5,1) NOT NULL DEFAULT 0.0 COMMENT '加权总分',
  `level` varchar(2) NOT NULL DEFAULT 'C' COMMENT 'A/B/C/D',
  `suggestion` varchar(600) DEFAULT NULL COMMENT '改进建议，多条用；分隔',
  `unsatisfied` varchar(400) DEFAULT NULL COMMENT '未满足条件，多条用；分隔',
  `input_snapshot` varchar(2000) DEFAULT NULL COMMENT '输入快照 JSON，保证可追溯',
  `calc_time` datetime NOT NULL COMMENT '计算时间',
  `create_by` bigint DEFAULT NULL COMMENT '触发人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  KEY `idx_activity` (`activity_id`),
  KEY `idx_level_time` (`level`, `calc_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='可行性评分快照';

CREATE TABLE `feasibility_correction` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_id` bigint NOT NULL COMMENT '关联 feasibility_snapshot.id',
  `activity_id` bigint NOT NULL COMMENT '关联 activity.id',
  `origin_score` decimal(5,1) NOT NULL COMMENT '原始总分，不被覆盖',
  `origin_level` varchar(2) NOT NULL COMMENT '原始等级',
  `new_level` varchar(2) NOT NULL COMMENT '人工修正后等级',
  `reason` varchar(200) NOT NULL COMMENT '修正原因，不少于5字',
  `operator_id` bigint NOT NULL COMMENT '修正人 sys_user.id',
  `oper_time` datetime NOT NULL COMMENT '修正时间',
  `create_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁',
  PRIMARY KEY (`id`),
  KEY `idx_snapshot` (`snapshot_id`),
  KEY `idx_activity` (`activity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='可行性评分人工修正';

























-- 附件元数据（发票与证明材料）

-- 支出流水业务类型按预算科目细化（否则看板「经费支出结构」只有一个扇区，看不出钱花在哪）
UPDATE fund_flow f
JOIN expense e ON f.biz_id = e.id
JOIN budget b ON e.budget_id = b.id
SET f.biz_type = CONCAT(b.item_type, '费')
WHERE f.direction = '支出' AND f.biz_type = '报销支出';

SET FOREIGN_KEY_CHECKS = 1;
-- 数据量自检：社团 24 / 成员 300+ / 活动 60+ / 报名 200+ / 预算 150+ / 报销 40+ / 流水 100+ / 公示 20+
